let hero = game.user.character;

if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t =>
    t.actor?.getFlag("vagabond-app", "rage")
  )?.actor;
}

if (!hero) return;

const hasRage = hero.getFlag("vagabond-app", "rage");
const hasMM = hero.getFlag("vagabond-app", "murdermode");
if (!hasRage) return;

const rageId = "T3WrjPCsOUipzXIR";
const mmId = "3dPNYwGcLBAfkskz";
const rageIsActive = hero.getFlag("vagabond-app", `ruleToggle_${rageId}`);
const mmIsActive = hero.getFlag("vagabond-app", `ruleToggle_${mmId}`);

if ((rageIsActive && mmIsActive) || (!rageIsActive && !mmIsActive)) {
  game.system.api.rules.toggleEffect(hero, rageId);
  game.system.api.rules.toggleEffect(hero, mmId);
}
else if (rageIsActive && !mmIsActive) {
  game.system.api.rules.toggleEffect(hero, rageId);
}
else if (!rageIsActive && mmIsActive) {
  game.system.api.rules.toggleEffect(hero, mmId);
}
